mapper.select:
select template_id, template_type, template_name, template_version, scenario, employment_type, social_type, post_level_scope, salary_version, file_url, file_name, file_size, file_hash, required_placeholders, optional_placeholders, employee_visible, read_confirmation_required, employee_sign_required, signature_position_json, company_seal_position_json, company_seal_required, match_condition_json, sort_order, status from oa_sign_template where template_id in
#{templateId}
order by template_id asc for update

select 
from oa_sign_plan_version
where plan_id = #{planId}
  and version_hash = #{versionHash}
limit 1

select coalesce(max(version_no), 0) + 1
from oa_sign_plan_version
where plan_id = #{planId}

select from oa_sign_plan_version_template where plan_version_id in
#{versionId}
order by plan_version_id asc, sort_order asc, template_type asc, id asc

mapper.update:
update oa_sign_plan_version
set matching_status = 'DISABLED'
where plan_id = #{planId}
  and version_id <> #{keepVersionId}
  and publish_status = 'PUBLISHED'
  and matching_status = 'ENABLED'
